const p = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : (msg.payload || {});

const NUMERIC = ['gas_raw', 'gas_avg', 'risk_code', 'body_temp', 'ambient_temp',
                 'fever_flag', 'room_temp', 'pressure', 'altitude'];
const fields = {};
for (const k of NUMERIC) {
    const v = p[k];
    if (typeof v === 'number' && isFinite(v)) fields[k] = v;
}
if (typeof p.risk_level === 'string') fields.risk_level = p.risk_level;
if (typeof p.timestamp === 'string') fields.rtc_time = p.timestamp;

if (fields.gas_avg === undefined) {
    node.warn('packet without gas_avg dropped');
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'gas_avg missing' };
    return [null, msg];
}

// Use the DS3231 time as the point timestamp when it is plausible
// (within 10 minutes of this server's clock); otherwise use arrival time.
const rtcMs = Date.parse(p.timestamp);
if (isFinite(rtcMs) && Math.abs(rtcMs - Date.now()) < 10 * 60 * 1000) {
    fields.time = new Date(rtcMs);
}

const tags = { device: String(p.device || 'esp32') };
node.status({ fill: fields.risk_code === 2 ? 'red' : fields.risk_code === 1 ? 'yellow' : 'green',
              shape: 'dot', text: `${fields.risk_level} gas=${fields.gas_avg} body=${fields.body_temp}` });

const reply = { statusCode: 200, payload: { ok: true }, req: msg.req, res: msg.res };
return [{ payload: [fields, tags] }, reply];
